<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Accessor\ConsentPurposeDescriptionAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ConsentPurposeDescriptionAccessor trait.
 *
 * Covers null default, string/VO assignment via withDescription,
 * getDescription/description accessors, and isDescriptionChanged with/without original.
 */
class ConsentPurposeDescriptionAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDescription creates a new instance with the Description set
     * from a string value, and getDescription returns the primitive string.
     */
    public function testWithDescriptionFromString(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeDescriptionAccessorUnitTest();

        // Act
        $result = $holder->withDescription('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getDescription());
    }
    /**
     * Asserts that withdescription has access to the value object
     * from a string value, and getDescription returns the primitive string.
     */
    public function testWithDescriptionFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeDescriptionAccessorUnitTest();

        // Act
        $result = $holder->withDescription('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->description()->value());
    }
    public function testChangedDescription(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeDescriptionAccessorUnitTest()->withDescription('one');
        $original = $holder->withDescription('one');
        $same = $holder->withDescription('one');
        $modified = $holder->withDescription('other');

        // Act
        $withSame = $original->isDescriptionChanged($same);
        $withDiferent = $original->isDescriptionChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithConsentPurposeDescriptionAccessorUnitTest
{
    use ConsentPurposeDescriptionAccessor;
}
